import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const require = createRequire(new URL("../../apps/api/package.json", import.meta.url));
const { Pool } = require("pg");
const { drizzle } = require("drizzle-orm/node-postgres");
const { migrate } = require("drizzle-orm/node-postgres/migrator");

/** SQL for synthetic recovery drills only; callers supply names generated by the drill. */
export class DisposableRecoveryRepository {
  constructor(baseUrl) {
    this.baseUrl = baseUrl;
    this.admin = new Pool({
      connectionString: baseUrl.toString(),
      max: 1,
      connectionTimeoutMillis: 5000,
    });
  }
  async create(name) {
    this.validateName(name);
    // No IF NOT EXISTS: a collision must fail, never adopt somebody else's database.
    await this.admin.query(`CREATE DATABASE "${name}"`);
  }
  async using(name, work) {
    this.validateName(name);
    const url = new URL(this.baseUrl);
    url.pathname = `/${name}`;
    const pool = new Pool({
      connectionString: url.toString(),
      max: 1,
      connectionTimeoutMillis: 5000,
    });
    try {
      return await work(pool);
    } finally {
      await pool.end();
    }
  }
  async fixture(name, marker) {
    await this.using(name, async (pool) => {
      await migrate(drizzle(pool), {
        migrationsFolder: fileURLToPath(
          new URL("../../apps/api/database/migrations", import.meta.url),
        ),
        migrationsSchema: "drizzle",
        migrationsTable: "__drizzle_migrations",
      });
      await pool.query(
        "INSERT INTO app.tenants(name,slug,status) VALUES('Synthetic recovery fixture',$1,'ACTIVE')",
        [marker],
      );
      // This public fixture table is not an application schema change. It exists only in this owned database.
      await pool.query(
        "CREATE TABLE public.phase8_restore_fixture(id integer PRIMARY KEY, marker text NOT NULL UNIQUE, is_deleted boolean NOT NULL DEFAULT false)",
      );
      await pool.query("INSERT INTO public.phase8_restore_fixture VALUES(1,$1,false),(2,$2,true)", [
        marker,
        `${marker}-deleted`,
      ]);
    });
  }
  async evidence(name) {
    return this.using(name, async (pool) => ({
      rows: (
        await pool.query(
          "SELECT id,marker,is_deleted FROM public.phase8_restore_fixture ORDER BY id",
        )
      ).rows,
      appTables: Number(
        (
          await pool.query(
            "SELECT count(*) AS count FROM information_schema.tables WHERE table_schema='app' AND table_type='BASE TABLE'",
          )
        ).rows[0].count,
      ),
      migrations: Number(
        (await pool.query("SELECT count(*) AS count FROM drizzle.__drizzle_migrations")).rows[0]
          .count,
      ),
      tenants: Number(
        (await pool.query("SELECT count(*) AS count FROM app.tenants WHERE is_deleted=false"))
          .rows[0].count,
      ),
    }));
  }
  async verifyConstraint(name) {
    return this.using(name, async (pool) => {
      try {
        await pool.query("INSERT INTO public.phase8_restore_fixture VALUES(1,'duplicate',false)");
      } catch (error) {
        if (error.code === "23505") return true;
        throw error;
      }
      return false;
    });
  }
  async drop(name) {
    this.validateName(name);
    await this.admin.query(`DROP DATABASE "${name}"`);
  }
  close() {
    return this.admin.end();
  }
  validateName(name) {
    if (!/^phase8_(source|restore)_[a-f0-9]{32}$/u.test(name))
      throw new Error("UNSAFE_RECOVERY_DATABASE_NAME");
  }
}
